alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(p_requester_id uuid, p_addressee_id uuid)
returns boolean
language sql
security definer
as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = p_requester_id and f.addressee_id = p_addressee_id)
       or (f.requester_id = p_addressee_id and f.addressee_id = p_requester_id)
    and f.status = 'accepted'
  );
$$;

create policy "R1: Authenticated users can read public posts"
on public.posts
for select
to authenticated
using (audience = 'public');

create policy "R1: Authenticated users can read friends' posts"
on public.posts
for select
to authenticated
using (
  audience = 'friends'
  and public.is_friend(auth.uid(), author_id)
);

create policy "R1: Authenticated users can read own posts"
on public.posts
for select
to authenticated
using (author_id = auth.uid());

create policy "R2: Authenticated users can insert own posts"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "R2: Authenticated users can update own posts"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "R2: Authenticated users can delete own posts"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "R3: Authenticated users can send friend requests"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

create policy "R4: Addressee can accept pending request"
on public.friendships
for update
to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

create policy "R5: Either party can view friendships"
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy "R5: Either party can delete friendships"
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

grant usage on schema public to authenticated;
grant select on public.posts to authenticated;
grant insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
