create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_auction public.auctions%rowtype;
  v_current_highest_bid numeric;
  v_min_increment numeric;
  v_starting_price numeric;
  v_ends_at timestamptz;
  v_new_highest_bid numeric;
begin
  -- Check if user is signed in
  if auth.uid() is null then
    raise exception 'User must be signed in to place a bid';
  end if;

  -- Fetch auction details
  select * into v_auction
  from public.auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction not found';
  end if;

  -- Check if auction has ended
  if v_auction.ends_at < now() then
    raise exception 'Auction has ended';
  end if;

  -- Check if caller is the seller
  if v_auction.seller_id = auth.uid() then
    raise exception 'Sellers cannot place bids on their own auctions';
  end if;

  -- Get current highest bid
  v_current_highest_bid := v_auction.highest_bid;

  -- Determine minimum valid bid
  if v_current_highest_bid is null then
    v_min_increment := v_auction.min_increment;
    v_starting_price := v_auction.starting_price;
    if p_amount < v_starting_price then
      raise exception 'Bid amount must be at least the starting price';
    end if;
  else
    v_min_increment := v_auction.min_increment;
    v_starting_price := v_auction.starting_price;
    if p_amount <= v_current_highest_bid then
      raise exception 'Bid amount must be higher than the current highest bid';
    end if;
    if p_amount < v_current_highest_bid + v_min_increment then
      raise exception 'Bid amount must be at least the current highest bid plus the minimum increment';
    end if;
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update the auction's highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
end;
$$;

grant execute on function public.place_bid to authenticated;
grant usage on schema public to authenticated;
grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
```

