using (false);

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_auction public.auctions;
  v_current_highest_bid numeric;
  v_min_increment numeric;
  v_starting_price numeric;
  v_is_seller boolean;
  v_ends_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Caller must be signed in';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction does not exist';
  end if;

  v_ends_at := v_auction.ends_at;
  v_min_increment := v_auction.min_increment;
  v_starting_price := v_auction.starting_price;
  v_is_seller := (v_auction.seller_id = auth.uid());

  if v_ends_at < now() then
    raise exception 'Auction has ended';
  end if;

  if v_is_seller then
    raise exception 'Seller cannot place a bid';
  end if;

  if p_amount <= 0 then
    raise exception 'Bid amount must be positive';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_starting_price then
      raise exception 'Bid amount must be at least the starting price';
    end if;
  else
    v_current_highest_bid := v_auction.highest_bid;
    if p_amount <= v_current_highest_bid + v_min_increment then
      raise exception 'Bid amount must be higher than current bid plus minimum increment';
    end if;
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  return p_amount;
end;
$$;

grant execute on function public.place_bid to authenticated;
